195	/**
196	 * Read, update, and atomically write settings while preserving unknown keys.
197	 *
198	 * The SDK's SettingsManager owns its lock when it writes known Pi settings.
199	 * CodePi's namespaced key is intentionally outside that API, so this helper
200	 * re-reads the complete file immediately before the atomic rename. A caller
201	 * that observes changed content gets one retry against the newest file rather
202	 * than clobbering the other writer's changes.
203	 */
204	export function writeCodePiSettingsMerge(
205		settingsPath: string,
206		updater: CodePiSettingsUpdater,
207		options?: CodePiSettingsMergeOptions,
208	): void {
209		for (let attempt = 0; attempt < 2; attempt++) {
210			const initialContent = readSettingsContent(settingsPath);
211			const current = parseSettingsContent(settingsPath, initialContent);
212			const next = updater({ ...current });
213			options?.beforeWriteCheck?.(attempt);
214			const latestContent = readSettingsContent(settingsPath);
215			if (latestContent !== initialContent) continue;
216			writeJsonFileAtomic(settingsPath, next);
217			return;
218		}
219		throw new Error(
220			`Settings changed while updating ${settingsPath}; please retry.`,
221		);
222	}
