 274	export function ensureDefaultTheme(): void {
 275		const settingsPath = getSettingsPath();
 276		const settings = readJsonFile<Record<string, unknown>>(settingsPath) ?? {};
 277		if (typeof settings.theme === "string") {
 278			// A theme was chosen explicitly — respect it.
 279			return;
 280		}
 281		settings.theme = DEFAULT_THEME;
 282		writeJsonFileAtomic(settingsPath, settings);
 283	}
