 285	/**
 286	 * Seed `<agentDir>/bin` with the fd/rg binaries pi's TUI waits for at
 287	 * startup. pi's `ensureTool()` otherwise downloads them over the network
 288	 * while init() awaits them — which makes the first seconds of a session
 289	 * look frozen. rg ships with this extension (@vscode/ripgrep-universal);
 290	 * fd is copied from a legacy `~/.pi/agent/bin` (or `~/.pi/bin`) when
 291	 * present. Idempotent; never overwrites an existing binary.
 292	 */
 293	export async function ensureRuntimeTools(agentDir: string): Promise<void> {
 294		const binDir = join(agentDir, "bin");
 295		mkdirSync(binDir, { recursive: true });
 296	
 297		const rgName = process.platform === "win32" ? "rg.exe" : "rg";
 298		const rgDest = join(binDir, rgName);
 299		if (!existsSync(rgDest)) {
 300			try {
 301				const mod = await import("@vscode/ripgrep-universal");
 302				copyBinary(mod.rgPath, rgDest);
 303			} catch {
 304				// rg unavailable — pi's ensureTool downloads it later if needed.
 305			}
 306		}
 307	
 308		const fdName = process.platform === "win32" ? "fd.exe" : "fd";
 309		const fdDest = join(binDir, fdName);
 310		if (!existsSync(fdDest)) {
 311			for (const srcDir of [
 312				join(homedir(), ".pi", "agent", "bin"),
 313				join(homedir(), ".pi", "bin"),
 314			]) {
 315				const src = join(srcDir, fdName);
 316				try {
 317					if (existsSync(src)) {
 318						copyBinary(src, fdDest);
 319						break;
 320					}
 321				} catch {
 322					/* unreadable/copy failed — try next source */
 323				}
 324			}
 325		}
 326	}
